const live = pm.response.json();
const baseline = JSON.parse(pm.collectionVariables.get('baselineContract'));
// Reduce a contract to the parts clients depend on.
const summarize = (spec) => {
const summary = {};
for (const [path, operations] of Object.entries(spec.paths)) {
for (const [method, op] of Object.entries(operations)) {
summary[method.toUpperCase() + ' ' + path] = {
responses: Object.keys(op.responses).sort(),
parameters: (op.parameters || []).map(p => p.in + ':' +
p.name).sort()
};
}
}

for (const [name, schema] of Object.entries(spec.components.schemas)) {

    const properties = schema.properties || {};

    const propertyTypes = {};
    const enums = {};

    for (const [propertyName, property] of Object.entries(properties)) {

        propertyTypes[propertyName] = property.type || null;

        if (property.enum) {
            enums[propertyName] = property.enum.slice().sort();
        }
    }

    summary['schema ' + name] = {
        properties: Object.keys(properties).sort(),
        required: (schema.required || []).slice().sort(),
        propertyTypes: propertyTypes,
        enums: enums
    };
}

return summary;
};
const before = summarize(baseline);
const after = summarize(live);
const allKeys = [...new
Set([...Object.keys(before), ...Object.keys(after)])];
const changed = allKeys.filter(k => JSON.stringify(before[k]) !==
JSON.stringify(after[k]));
pm.test('Live contract matches the baseline', () => {
pm.expect(changed, 'Changed: ' + changed.join(', ')).to.be.empty;
});

const base = pm.variables.get('baseUrl');
const post = (path, obj, cb) => pm.sendRequest({
    url: base + path, method: 'POST',
    header: { 'Content-Type': 'application/json' },
    body: { mode: 'raw', raw: JSON.stringify(obj) }
}, (e, r) => cb(r.json()));
post('/api/students', { name: 'LSC Student', major: 'Art', gpa: 3.0 }, s => {
    pm.variables.set('lscStudentId', s.id);
    post('/api/courses', { name: 'LSC Course', instructor: 7, maxSize: 5, room: 'R2' }, c => {
        pm.variables.set('lscCourseId', c.id);
        pm.sendRequest({
            url: base + '/api/courses/addStudent/' + c.id, method: 'PUT',
            header: { 'Content-Type': 'application/json' },
            body: { mode: 'raw', raw: String(s.id) }
        }, () => {});
    });
});

const Ajv = require('ajv');
const spec = JSON.parse(pm.collectionVariables.get('contract'));
const ajv = new Ajv({ allErrors: true, unknownFormats: 'ignore', schemaId: 'auto', validateSchema: false, logger: false });
ajv.addSchema(spec, 'spec');
const check = (name, body) => ajv.validate({ $ref: 'spec#/components/schemas/' + name }, body);

pm.test('List student courses returns 200', () => pm.response.to.have.status(200));
