(async () => { const base = pm.variables.get('baseUrl');
const call = (method, path, body) => new Promise(res => pm.sendRequest({ url: base + path, method, header: { 'Content-Type': 'application/json' }, body: body === undefined ? undefined : { mode: 'raw', raw: JSON.stringify(body) } }, (e, r) => res(r)));
const mk = async (o = {}) => (await call('POST', '/api/students', { name: 'Dyn', major: 'Dyn', gpa: 3, ...o })).json().id;
const mc = async (o = {}) => (await call('POST', '/api/courses', { name: 'Dyn', instructor: 9, maxSize: 5, room: 'R', ...o })).json().id;
const s = await mk(), c = await mc({ name: 'WfA' });
await call('PUT', '/api/courses/addStudent/' + c, s);
const en1 = (await call('GET', '/api/courses/getEnrollment/' + c)).json();
const st1 = (await call('GET', '/api/students/' + s)).json();
const cs1 = (await call('GET', '/api/students/' + s + '/courses'));
const rem = await call('PUT', '/api/courses/removeStudent/' + c, { studentId: s });
const en2 = (await call('GET', '/api/courses/getEnrollment/' + c)).json();
const st2 = (await call('GET', '/api/students/' + s)).json();
pm.test('After enroll: enrollment is 1', () => pm.expect(en1).to.equal(1));
pm.test("After enroll: student's courses includes WfA", () => pm.expect(st1.courses).to.include('WfA'));
pm.test("After enroll: /students/{id}/courses returns 200", () => pm.expect(cs1.code).to.equal(200));
pm.test('Remove with the documented body returns 200', () => pm.expect(rem.code).to.equal(200));
pm.test('After remove: enrollment is 0', () => pm.expect(en2).to.equal(0));
pm.test("After remove: student's courses is empty", () => pm.expect(st2.courses).to.be.empty); })();

