const mk = async (o = {}) => (await call('POST', '/api/students', { name: 'Dyn', major: 'Dyn', gpa: 3, ...o })).json().id;
const mc = async (o = {}) => (await call('POST', '/api/courses', { name: 'Dyn', instructor: 9, maxSize: 5, room: 'R', ...o })).json().id;
const c = await mc({ maxSize: 1 }), s1 = await mk(), s2 = await mk();
const a1 = await call('PUT', '/api/courses/addStudent/' + c, s1);
const a2 = await call('PUT', '/api/courses/addStudent/' + c, s2);
const rem = await call('PUT', '/api/courses/removeStudent/' + c, { studentId: s1 });
const a3 = await call('PUT', '/api/courses/addStudent/' + c, s2);
const en = (await call('GET', '/api/courses/getEnrollment/' + c)).json();
pm.test('First student fits (200)', () => pm.expect(a1.code).to.equal(200));
pm.test('Second student on a full course returns 409', () => pm.expect(a2.code).to.equal(409));
pm.test('Remove frees the seat (200)', () => pm.expect(rem.code).to.equal(200));
pm.test('Second student now fits (200)', () => pm.expect(a3.code).to.equal(200));
pm.test('Enrollment ends at 1', () => pm.expect(en).to.equal(1)); })();

