const c1 = await mc({ name: 'WfC1' }), c2 = await mc({ name: 'WfC2' });
const s = await mk({ courses: [c1] });
const upd = await call('PUT', '/api/students/' + s, { name: 'Dyn', major: 'Dyn', gpa: 3, courses: [c2] });
const st = (await call('GET', '/api/students/' + s)).json();
const e1 = (await call('GET', '/api/courses/getEnrollment/' + c1)).json();
const e2 = (await call('GET', '/api/courses/getEnrollment/' + c2)).json();
pm.test('Update with courses returns 200', () => pm.expect(upd.code).to.equal(200));
pm.test('Student now lists only WfC2', () => pm.expect(st.courses).to.deep.equal(['WfC2']));
pm.test('Old course roster is now empty', () => pm.expect(e1).to.equal(0));
pm.test('New course roster has the student', () => pm.expect(e2).to.equal(1)); })();

