const mk = async (o = {}) => (await call('POST', '/api/students', { name: 'Dyn', major: 'Dyn', gpa: 3, ...o })).json().id;
const mc = async (o = {}) => (await call('POST', '/api/courses', { name: 'Dyn', instructor: 9, maxSize: 5, room: 'R', ...o })).json().id;
const raw = (method, path, text) => new Promise(res => pm.sendRequest({ url: base + path, method, header: { 'Content-Type': 'application/json' }, body: { mode: 'raw', raw: text } }, (e, r) => res(r)));
const s = await mk(), c = await mc();
const bad1 = await raw('POST', '/api/students', '{ "name": "x", ');
const bad2 = await call('POST', '/api/students', { name: 'x', major: 'y', gpa: 'abc' });
const bad3 = await call('POST', '/api/students', { name: 'x' });
const noStu = await call('PUT', '/api/courses/addStudent/' + c, 99999999);
const noCrs = await call('PUT', '/api/courses/addStudent/99999999', s);
pm.test('Malformed JSON returns 400', () => pm.expect(bad1.code).to.equal(400));
pm.test('Wrong type for gpa returns 400', () => pm.expect(bad2.code).to.equal(400));
pm.test('Missing major and gpa returns 400', () => pm.expect(bad3.code).to.equal(400));
pm.test('Add unknown student returns 404', () => pm.expect(noStu.code).to.equal(404));
pm.test('Add to unknown course returns 404', () => pm.expect(noCrs.code).to.equal(404)); })();

