const mk = async (o = {}) => (await call('POST', '/api/students', { name: 'Dyn', major: 'Dyn', gpa: 3, ...o })).json().id;
const mc = async (o = {}) => (await call('POST', '/api/courses', { name: 'Dyn', instructor: 9, maxSize: 5, room: 'R', ...o })).json().id;
const s = await mk(), c = await mc({ name: 'GoneCourse' });
await call('PUT', '/api/courses/addStudent/' + c, s);
const del = await call('DELETE', '/api/courses/' + c);
const stu = await call('GET', '/api/students/' + s);
pm.test('Deleting a course with a roster returns 204', () => pm.expect(del.code).to.equal(204));
pm.test('Student still exists after the course is deleted', () => pm.expect(stu.code).to.equal(200));
pm.test("Student's courses no longer lists the deleted course", () => pm.expect(stu.json().courses).to.not.include('GoneCourse')); })();

