const call = (method, path, body) => new Promise(res => pm.sendRequest({ url: base + path, method, header: { 'Content-Type': 'application/json' }, body: body === undefined ? undefined : { mode: 'raw', raw: JSON.stringify(body) } }, (e, r) => res(r)));
const codes = [];
for (const g of [0, 4, -0.01, 4.01]) codes.push((await call('POST', '/api/students', { name: 'Dyn', major: 'Dyn', gpa: g })).code);
pm.test('gpa 0 (on lower limit) accepted', () => pm.expect([200, 201]).to.include(codes[0]));
pm.test('gpa 4 (on upper limit) accepted', () => pm.expect([200, 201]).to.include(codes[1]));
pm.test('gpa -0.01 (below range) rejected with 400', () => pm.expect(codes[2]).to.equal(400));
pm.test('gpa 4.01 (above range) rejected with 400', () => pm.expect(codes[3]).to.equal(400));
})();

