const mk = async (o = {}) => (await call('POST', '/api/students', { name: 'Dyn', major: 'Dyn', gpa: 3, ...o })).json().id;
const mc = async (o = {}) => (await call('POST', '/api/courses', { name: 'Dyn', instructor: 9, maxSize: 5, room: 'R', ...o })).json().id;
const s = await mk(), c = await mc();
await call('PUT', '/api/courses/addStudent/' + c, s);
const del = await call('DELETE', '/api/students/' + s);
pm.test('Delete of an enrolled student returns 204', () => pm.expect(del.code).to.equal(204));
const after = await call('GET', '/api/students/' + s);
pm.test('Deleted student returns 404 on GET', () => pm.expect(after.code).to.equal(404));
const en = (await call('GET', '/api/courses/getEnrollment/' + c)).json();
pm.test('Enrollment is 0 after the student is deleted', () => pm.expect(en).to.equal(0)); })();

