const mk = async (o = {}) => (await call('POST', '/api/students', { name: 'Dyn', major: 'Dyn', gpa: 3, ...o })).json().id;
const mc = async (o = {}) => (await call('POST', '/api/courses', { name: 'Dyn', instructor: 9, maxSize: 5, room: 'R', ...o })).json().id;
const c1 = await mc({ name: 'PathA' });
const sA = await mk({ courses: [c1] });
const sB = await mk();
const c2 = await mc({ name: 'PathB', roster: [sB] });
const e1 = (await call('GET', '/api/courses/getEnrollment/' + c1)).json();
const e2 = (await call('GET', '/api/courses/getEnrollment/' + c2)).json();
const stA = (await call('GET', '/api/students/' + sA)).json();
const stB = (await call('GET', '/api/students/' + sB)).json();
pm.test('Student created with courses appears on the course roster', () => pm.expect(e1).to.equal(1));
pm.test("That student's course list shows the course", () => pm.expect(stA.courses).to.include('PathA'));
pm.test('Course created with a roster counts the student', () => pm.expect(e2).to.equal(1));
pm.test("That student's course list shows the course (roster path)", () => pm.expect(stB.courses).to.include('PathB')); })();

